queries.query:
// Query for Available Filters
availableFilters = from(bucket: "efd/autogen")
  |> range(start: -inf)
  |> filter(fn: (r) => r["_measurement"] == "lsst.sal.MTCamera.logevent_availableFilters" and r["_field"] == "filterNames")
  |> last()
  |> map(fn: (r) => ({
    category: "Filters",
    availableFilters: r._value
  }))
  |> keep(columns: ["category", "availableFilters"])

// Query for Current Filter
currentFilter = from(bucket: "efd/autogen")
  |> range(start: -inf)
  |> filter(fn: (r) => r["_measurement"] == "lsst.sal.MTCamera.logevent_endSetFilter" and r["_field"] == "filterName")
  |> last()
  |> map(fn: (r) => ({
    category: "Filters",
    currentFilter: r._value
  }))
  |> keep(columns: ["category", "currentFilter"])

// Query for Commanded Filter
commandedFilter = from(bucket: "efd/autogen")
  |> range(start: -inf)
  |> filter(fn: (r) => r["_measurement"] == "lsst.sal.MTCamera.command_setFilter" and r["_field"] == "name")
  |> last()
  |> map(fn: (r) => ({
    category: "Filters",
    commandedFilter: r._value
  }))
  |> keep(columns: ["category", "commandedFilter"])

// Join Available Filters and Current Filter
filtersDashboard1 = join(
  tables: {available: availableFilters, current: currentFilter},
  on: ["category"]
)

// Join the Result with Commanded Filter
filtersDashboard2 = join(
  tables: {filtersDashboard1: filtersDashboard1, commanded: commandedFilter},
  on: ["category"]
)

// Final Output
filtersDashboard2
  |> keep(columns: ["availableFilters", "currentFilter", "commandedFilter"])

