queries.query:
// Define the bucket. 
_bucket = "efd/autogen"
_range = -7d

// --- Query for Azimuth Axis Status ---
azimuth_status_stream = from(bucket: _bucket)
  |> range(start: _range) // Get the absolute latest record
  |> filter(fn: (r) => r._measurement == "lsst.sal.MTMount.logevent_azimuthHomed" and r._field == "homed")
  |> last() // Get the very last record
  |> map(fn: (r) => ({
      // Define a consistent set of columns for the union operation
      axis: "Azimuth", // Label for this axis
      status: if r._value == true then "HOMED" else "NOT HOMED", // Human-readable status
      last_updated: r._time // Timestamp of this specific status update
  }))
  // Explicitly keep only the columns that will be displayed and merged
  |> keep(columns: ["axis", "status", "last_updated"])

// --- Query for Elevation Axis Status ---
elevation_status_stream = from(bucket: _bucket)
  |> range(start: _range) // Get the absolute latest record 
  |> filter(fn: (r) => r._measurement == "lsst.sal.MTMount.logevent_elevationHomed" and r._field == "homed")
  |> last() // Get the very last record
  |> map(fn: (r) => ({
      // Define the same consistent set of columns for the union operation
      axis: "Elevation", // Label for this axis
      status: if r._value == true then "HOMED" else "NOT HOMED", // Human-readable status
      last_updated: r._time // Timestamp of this specific status update
  }))
  // Explicitly keep only the columns that will be displayed and merged
  |> keep(columns: ["axis", "status", "last_updated"])

// --- Union the two streams into a single table for display ---
union(
  tables: [azimuth_status_stream, elevation_status_stream]
)
// Sort the results for consistent display order (e.g., Azimuth then Elevation)
|> sort(columns: ["axis"], desc: false)

