queries.query:
from(bucket: "efd/autogen")
  |> range(start: -inf) // Large range to ensure the most recent record is found
  |> filter(fn: (r) => r["_measurement"] == "lsst.sal.MTDomeTrajectory.logevent_followingMode" and r["_field"] == "enabled")
  |> last() // Fetch the most recent record
  |> map(fn: (r) => ({
    _time: r._time,
    enabled: if r._value == true then "ENABLED" else "DISABLED"
    }))
  |> keep(columns: ["_time", "enabled"]) // Keep only time and enabled status

